<section ng-controller="verifikasiPembayaranController" ng-cloak><div class="alert alert-danger" ng-if="errorMessage" ng-bind="errorMessage"></div><div class="alert alert-success" ng-if="successMessage" ng-bind="successMessage"></div><div class="alert alert-warning" ng-if="!loading&&!activePeriod">Belum ada periode akademik aktif.</div>
<article class="card sitara-card"><header class="card-header border-0 pb-0"><div class="module-toolbar d-flex flex-column flex-xl-row justify-content-between align-items-xl-center gap-3"><div><h2 class="sitara-card-title">Pembayaran mahasiswa</h2><p class="sitara-card-subtitle mb-0">Periksa pembayaran sebelum memperbarui saldo tagihan.</p></div><div class="d-flex flex-wrap gap-2"><select class="form-select form-select-sm" ng-model="statusFilter"><option value="">Semua status</option><option value="MENUNGGU">Menunggu</option><option value="DITERIMA">Diterima</option><option value="DITOLAK">Ditolak</option></select><input type="search" class="form-control form-control-sm" placeholder="Cari pembayaran" ng-model="searchText"><button class="btn btn-sm btn-primary text-nowrap" type="button" ng-click="openCreate()" ng-disabled="!bills.length">Catat pembayaran</button></div></div></header>
<div class="table-responsive mt-3"><table class="table sitara-table mb-0"><thead><tr><th>Nomor pembayaran</th><th>Mahasiswa</th><th>Tagihan</th><th>Metode</th><th>Tanggal</th><th class="text-end">Nominal</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody><tr ng-if="loading"><td colspan="8" class="sitara-empty">Memuat pembayaran...</td></tr><tr ng-repeat="x in (filteredDatas=(datas|filter:searchText|filter:{status:statusFilter})) track by x.id"><td><div class="table-main" ng-bind="x.payment_no"></div><small ng-bind="x.reference_no||'Tanpa referensi'"></small></td><td><div class="table-main" ng-bind="x.full_name"></div><small ng-bind="x.nim"></small></td><td ng-bind="x.bill_numbers"></td><td ng-bind="x.method_name"></td><td ng-bind="x.payment_date"></td><td class="text-end amount-main" ng-bind="rupiah(x.amount)"></td><td><span class="sitara-status" ng-bind="statusLabel(x.status)"></span></td><td><div class="sitara-row-actions justify-content-end"><a class="btn btn-sm btn-outline-secondary" ng-if="x.proof_file_path" ng-href="proofUrl(x)" target="_blank" rel="noopener">Bukti</a><button class="btn btn-sm btn-outline-success" ng-if="x.status==='MENUNGGU'" ng-click="accept(x)" ng-disabled="workingId===x.id">Terima</button><button class="btn btn-sm btn-outline-danger" ng-if="x.status==='MENUNGGU'" ng-click="openReject(x)" ng-disabled="workingId===x.id">Tolak</button></div><span class="small text-gray-500" ng-if="x.status!=='MENUNGGU'" ng-bind="x.verified_at||'Sudah diproses'"></span></td></tr><tr ng-if="!loading&&!datas.length"><td colspan="8" class="sitara-empty">Belum ada pembayaran pada periode aktif.</td></tr></tbody></table></div></article>

<div class="modal fade" id="paymentModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><form name="paymentForm" ng-submit="save(paymentForm)" novalidate><div class="modal-header"><div><h2 class="modal-title h5">Catat pembayaran</h2><p class="small text-gray-600 mb-0">Pembayaran baru berstatus menunggu sampai diverifikasi.</p></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body p-4"><div class="alert alert-danger" ng-if="errorMessage" ng-bind="errorMessage"></div><div class="row g-3"><div class="col-12"><label class="form-label">Tagihan mahasiswa</label><select name="student_bill_id" class="form-select" ng-model="model.student_bill_id" required><option value="">Pilih tagihan</option><option ng-repeat="x in bills" ng-value="x.id" ng-bind="x.bill_no+' — '+x.nim+' · '+x.full_name+' (sisa '+rupiah(x.outstanding_amount)+')'"></option></select></div><div class="col-md-6"><label class="form-label">Metode pembayaran</label><select name="payment_method_id" class="form-select" ng-model="model.payment_method_id" required><option value="">Pilih metode</option><option ng-repeat="x in methods" ng-value="x.id" ng-bind="x.code+' — '+x.name"></option></select></div><div class="col-md-6"><label class="form-label">Tanggal pembayaran</label><input type="datetime-local" class="form-control" ng-model="model.payment_date" required></div><div class="col-md-6"><label class="form-label">Nominal</label><div class="input-group"><input type="number" min="1" class="form-control" ng-model="model.amount" required><button type="button" class="btn btn-outline-primary" ng-click="useOutstanding()" ng-disabled="!selectedBill()">Isi sisa</button></div></div><div class="col-md-6"><label class="form-label">Nomor referensi</label><input class="form-control" maxlength="100" ng-model="model.reference_no"></div><div class="col-12"><label class="form-label">Catatan</label><textarea class="form-control" rows="2" ng-model="model.notes"></textarea></div></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-gray" data-bs-dismiss="modal">Batal</button><button type="submit" class="btn btn-primary" ng-disabled="saving" ng-bind="saving?'Menyimpan...':'Simpan pembayaran'"></button></div></form></div></div></div>

<div class="modal fade" id="rejectPaymentModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form name="rejectPaymentForm" ng-submit="reject(rejectPaymentForm)" novalidate><div class="modal-header"><h2 class="modal-title h5">Tolak pembayaran</h2><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="payment-info mb-3">Pembayaran: <strong ng-bind="rejectModel.payment_no"></strong></div><label class="form-label">Alasan penolakan</label><textarea name="notes" class="form-control" rows="3" ng-model="rejectModel.notes" required></textarea></div><div class="modal-footer"><button type="button" class="btn btn-outline-gray" data-bs-dismiss="modal">Batal</button><button type="submit" class="btn btn-danger" ng-disabled="saving" ng-bind="saving?'Memproses...':'Tolak pembayaran'"></button></div></form></div></div></div>
</section>
<script>window.SITARA_PAYMENT_VERIFICATION_CONFIG=<?= json_encode(['baseUrl'=>site_url('keuangan/verifikasi')],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;window.SITARA_CSRF=<?= json_encode(['header'=>$csrfHeader,'hash'=>$csrfHash],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;</script>
<?= $this->endSection() ?>
